def read(value):
    try:
        raise ValueError()
    except ValueError as value:
        pass
    if value is None and value is not None:
        return 1
    return 2

def read(value):
    def clear():
        nonlocal value
        del value
    clear()
    if value is None and value is not None:
        return 1
    return 2
